const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.addInitScript(() => {
    const proto = CanvasRenderingContext2D.prototype;
    for (const name of Object.getOwnPropertyNames(proto)) {
      if (name === 'constructor') continue;
      const descriptor = Object.getOwnPropertyDescriptor(proto, name);
      if (descriptor && typeof descriptor.value === 'function') {
        const value = ['createLinearGradient', 'createRadialGradient'].includes(name)
          ? () => ({ addColorStop() {} }) : () => {};
        Object.defineProperty(proto, name, { ...descriptor, value });
      }
    }
  });
  await page.goto('http://localhost:3002');
  await page.click('#startButton');
  await page.click('#briefContinue');
  const initial = await page.evaluate(() => window.__umbraDebug);
  await page.keyboard.down('d');
  await page.waitForFunction(() => window.__umbraDebug.x >= 460, { timeout: 15000 });
  await page.keyboard.up('d');
  await page.keyboard.press('e');
  const relay = await page.evaluate(() => window.__umbraDebug);
  await page.keyboard.press('Escape');
  const paused = await page.evaluate(() => window.__umbraDebug.state);
  await page.click('#resumeButton');
  const resumed = await page.evaluate(() => window.__umbraDebug.state);
  console.log(JSON.stringify({ initial, relay, paused, resumed, errors }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });

