.skip-cinematic{position:absolute;z-index:3;top:5%;right:5%;min-height:42px;padding:0 15px;border:1px solid rgba(172,190,183,.4);border-radius:2px;background:rgba(7,12,16,.72);color:#c6ceca;font:10px var(--mono);letter-spacing:.1em;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
.skip-cinematic:hover,.skip-cinematic:focus-visible{background:rgba(27,42,45,.95);border-color:var(--cyan);color:#fff;outline:none}
