.hud{ .hud{position:absolute;inset:0;z-index:6;pointer-events:none}

.mobile-controls{ .mobile-controls{position:absolute;z-index:7;inset:auto 0 5% 0;pointer-events:none;justify-content:space-between;padding:0 5%}

.story-caption{ .story-caption{position:absolute;z-index:8;bottom:14%;left:50%;transform:translateX(-50%);width:min(590px,80%);padding:15px 20px 17px;background:linear-gradient(90deg,#090d11ed,#101519e8);border-left:2px solid var(--cyan);box-shadow:0 8px 35px #0008}

.interact-prompt{ .interact-prompt{position:absolute;left:50%;top:75%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;color:#e4e7df;font-size:9px;letter-spacing:.13em;text-shadow:0 2px 5px #000}

.toast{ .toast{position:absolute;top:18%;left:50%;transform:translateX(-50%);padding:10px 18px;background:#090e13d9;border-left:2px solid var(--red);font-size:10px;letter-spacing:.09em;color:#e5e6db;opacity:0;transition:opacity .3s}

