.hud-top{position:absolute;left:4.2%;right:4.2%;top:4.1%;display:flex;align-items:flex-start;justify-content:space-between;text-shadow:0 2px 6px #000}

.hud-bottom{position:absolute;left:4.2%;right:4.2%;bottom:4.5%;display:flex;align-items:center;gap:28px;text-shadow:0 2px 6px #000}

.objective{position:absolute;left:50%;transform:translateX(-50%);text-align:center;border-top:1px solid #89929288;padding:8px 25px 0}

.sector{text-align:right}

