.ammo{display:flex;align-items:baseline;gap:5px;border-left:1px solid #657071;padding-left:22px}

.collectibles{margin-left:auto}

.medkits{margin-left:auto;display:flex;align-items:baseline;gap:8px}

.controls-hint{position:absolute;left:4.2%;right:auto;bottom:10%;font-size:8px;color:#899293;letter-spacing:.08em}

