+ .move-controls .jump-button{width:66px;color:var(--cyan)}
+ .jump-button span,.mobile-actions button span{font:20px/1 var(--display)}
+ .jump-button small,.mobile-actions button small{font:7px/1 var(--mono);letter-spacing:.04em}
+ .mobile-actions{position:absolute;right:3.5%;bottom:4%;display:grid;grid-template-columns:86px 61px 61px;grid-template-rows:44px 44px;gap:6px;align-items:stretch;pointer-events:auto}
+ .mobile-actions button{width:auto;height:auto;min-width:0;font:inherit}
+ .mobile-actions .fire-button{grid-row:1/3;border-radius:50%;border-color:rgba(228,81,72,.72);background:radial-gradient(circle at 35% 28%,rgba(131,51,46,.95),rgba(42,19,20,.96));color:#fff1e9}
+ .mobile-actions .fire-button span{font-size:25px}
+ .mobile-actions #mobileUse{color:var(--cyan)}
+ .mobile-actions #mobileReload{color:#e3d7ab}
+ .mobile-actions #mobileMed{grid-column:2/4}
+ .mobile-pause{position:absolute;top:3%;right:3.5%;width:42px;height:40px;pointer-events:auto;font:19px/1 var(--mono)}
+ .story-caption{bottom:35%;width:min(88%,560px)}
+ .interact-prompt{top:59%}
+}
+@media(max-width:700px) and (orientation:portrait){.hud-bottom{bottom:32%}.story-caption{bottom:35%}}
+@media(max-height:430px) and (max-width:900px){.hud-bottom{bottom:35%}.mobile-actions{grid-template-rows:40px 40px}.mobile-controls .move-controls{bottom:3%}.mobile-actions{bottom:3%}}

