@media(max-height:430px) and (max-width:900px){.hud-bottom{bottom:35%}.mobile-actions{grid-template-rows:40px 40px}.mobile-controls .move-controls{bottom:3%}.mobile-actions{bottom:3%}}

/* Refined, thumb-first interface and a true portrait game viewport. */
button{cursor:pointer;touch-action:manipulation}
button:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
.primary-button,.text-button{transition:transform .18s ease,background .18s ease,border-color .18s ease}
.primary-button:hover,.text-button:hover{transform:translateY(-2px);border-color:var(--cyan);background-color:rgba(38,67,68,.88)}
.title-screen{background:radial-gradient(ellipse at 76% 48%,rgba(34,66,69,.19),transparent 40%),linear-gradient(90deg,rgba(5,8,13,.98),rgba(5,8,13,.76) 58%,rgba(5,8,13,.48)),linear-gradient(0deg,rgba(5,8,13,.76),transparent 52%)}
.title-copy h1{max-width:620px;text-shadow:0 6px 30px #0009}
.title-copy h1 em{color:#cbd2cc;font-style:normal}
.title-desc{max-width:390px;line-height:1.75}
.primary-button{border:1px solid rgba(123,201,194,.58);background:linear-gradient(115deg,rgba(27,52,54,.96),rgba(10,18,22,.96));box-shadow:0 8px 28px #0005,inset 0 1px #ffffff12;letter-spacing:.13em}
.hud-top .objective,.hud-top .sector,.hud-brand,.hud-bottom>div{background:linear-gradient(135deg,rgba(7,13,16,.91),rgba(10,17,20,.78));border:1px solid rgba(155,183,175,.19);box-shadow:0 7px 22px #0004}
.hud-top .objective{border-left:2px solid var(--red)}
.hud-top .sector{border-bottom:2px solid var(--cyan)}
.hud-bottom>div{padding:9px 12px;border-radius:4px}
.story-caption{border:1px solid rgba(123,201,194,.34);border-left:3px solid var(--cyan);background:rgba(5,10,14,.94);box-shadow:0 10px 32px #0009}
.interact-prompt{border:1px solid rgba(123,201,194,.55);background:rgba(7,16,19,.94);box-shadow:0 6px 20px #0008}
.mobile-controls{z-index:30}
.mobile-controls button{position:relative;overflow:hidden;min-height:44px;touch-action:none;-webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none;transition:filter .12s,transform .12s,background .12s}
.mobile-controls button:active{filter:brightness(1.35);transform:scale(.96)}
.mobile-controls button:after{content:'';position:absolute;inset:0;pointer-events:none;border-radius:inherit;background:linear-gradient(145deg,#ffffff12,transparent 58%)}
.mobile-controls .mobile-pause{border:1px solid rgba(185,202,195,.4);background:rgba(8,15,18,.9);box-shadow:0 5px 16px #0008}
.pause-screen,.end-screen{z-index:40}

@media(max-width:700px){
 .game-shell{width:100vw;height:100dvh;top:0;left:0;transform:none;margin:0;background:radial-gradient(ellipse at 50% 42%,#182126 0%,#080d12 64%,#05070a 100%);box-shadow:none}
 .title-screen{padding:calc(env(safe-area-inset-top) + 22px) 7% calc(env(safe-area-inset-bottom) + 24px);background:radial-gradient(ellipse at 82% 43%,rgba(64,103,103,.19),transparent 45%),linear-gradient(90deg,rgba(5,8,13,.98),rgba(5,8,13,.72)),linear-gradient(0deg,rgba(5,8,13,.7),transparent 62%)}
 .title-top{gap:12px;font-size:8px;letter-spacing:.15em}
 .title-copy{max-width:440px;margin:auto 0}
 .title-copy .eyebrow{font-size:8px;letter-spacing:.17em;margin-bottom:14px}
 .title-copy h1{font-size:clamp(60px,15vw,88px);line-height:.82;letter-spacing:0}
 .title-desc{font-size:11px;line-height:1.75;margin:18px 0 20px}
 .primary-button{min-height:54px;min-width:min(100%,280px);font-size:10px}
 .title-hint{font-size:8px;letter-spacing:.12em}
 .title-bottom{font-size:7px;letter-spacing:.1em}
 .briefing{padding:20px 0;background:rgba(5,8,13,.94)}
 .brief-card{width:min(88%,460px);margin:0 auto;padding:24px 21px;border:1px solid rgba(123,201,194,.24);background:linear-gradient(145deg,rgba(16,28,32,.98),rgba(7,12,16,.98));box-shadow:0 18px 55px #0008}
 .brief-kicker{font-size:8px;letter-spacing:.13em}
 .brief-card h2{font-size:clamp(42px,11vw,58px);line-height:.9}
 .brief-text{font-size:11px;line-height:1.75}
 .brief-card .text-button{width:100%;justify-content:space-between}
 .controls-hint{display:none}
 .mobile-controls{inset:0;display:block;padding:0;pointer-events:none}
 .mobile-controls .move-controls{position:absolute;left:max(12px,env(safe-area-inset-left));right:auto;bottom:calc(env(safe-area-inset-bottom) + 22px);display:flex;align-items:flex-end;gap:7px;pointer-events:auto}
 .move-controls button,.mobile-actions button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;border:1px solid rgba(173,195,186,.48);border-radius:13px;background:linear-gradient(145deg,rgba(27,39,42,.96),rgba(8,14,17,.97));color:#edf1e9;box-shadow:0 6px 18px #0009,inset 0 1px #ffffff12}
 .mobile-controls .move-controls button{width:49px;height:53px;font:26px/1 var(--display)}
 .mobile-controls .move-controls .jump-button{width:56px;color:var(--cyan)}
 .jump-button small,.mobile-actions button small{font:7px/1 var(--mono);letter-spacing:.04em}
 .mobile-controls .mobile-actions{position:absolute;left:auto;right:max(12px,env(safe-area-inset-right));bottom:calc(env(safe-area-inset-bottom) + 22px);top:auto;display:grid;grid-template-columns:70px 47px 47px;grid-template-rows:43px 43px;gap:7px;pointer-events:auto}
 .mobile-controls .mobile-actions button{width:auto;height:auto;min-width:0;font:inherit}
 .mobile-controls .mobile-actions .fire-button{grid-column:1;grid-row:1/3;border-radius:22px;border-color:rgba(228,105,91,.76);background:radial-gradient(circle at 35% 25%,rgba(137,58,50,.98),rgba(49,21,22,.99));color:#fff2e8}
 .mobile-actions .fire-button span{font-size:24px}
 .mobile-controls .mobile-actions #mobileUse{grid-column:2;grid-row:1;color:var(--cyan)}
 .mobile-controls .mobile-actions #mobileReload{grid-column:3;grid-row:1;color:#e3d7ab}
 .mobile-controls .mobile-actions #mobileMed{grid-column:2/4;grid-row:2}
 .mobile-controls .mobile-pause{position:absolute;top:calc(env(safe-area-inset-top) + 12px);right:max(12px,env(safe-area-inset-right));left:auto;bottom:auto;width:44px;height:42px;pointer-events:auto;font:18px/1 var(--mono)}
 .hud{position:absolute;inset:0;z-index:7;pointer-events:none}
 .hud-top{position:absolute;left:12px;right:68px;top:calc(env(safe-area-inset-top) + 12px);display:grid;grid-template-columns:1fr auto;align-items:start;gap:8px}
 .hud-brand{min-width:0;padding:7px 9px;border-radius:4px;gap:8px}
 .hud-brand small{font-size:6px;letter-spacing:.06em}
 .hud-brand b{font-size:10px}
 .objective{position:absolute!important;left:0;right:0;top:calc(100dvh * .125);width:auto!important;padding:8px 10px!important}
 .objective small,.sector small{font-size:7px}
 .objective b,.sector b{font-size:9px;line-height:1.25}
 .sector{grid-column:2;grid-row:1;margin:0;padding:7px 9px!important;text-align:right;border-radius:4px}
 .hud-bottom{position:absolute;left:12px;right:12px;top:auto;bottom:calc(env(safe-area-inset-bottom) + 19%);display:grid;grid-template-columns:1.25fr 1fr 1fr;gap:6px;align-items:stretch}
 .hud-bottom>div{min-width:0;padding:7px 8px;border-radius:4px}
 .vitals{grid-template-columns:auto minmax(28px,1fr) 22px;gap:5px}
 .hud-label{font-size:6px;letter-spacing:.08em}
 .health-track{height:4px}
 .health-value,.vitals>b,.ammo>b,.collectibles>b,.medkits>b{font-size:11px}
 .ammo{padding-left:8px!important;gap:4px}
 .ammo-icon{font-size:10px}
 .collectibles,.medkits{margin:0!important;display:flex;align-items:center;gap:4px}
 .collectibles .hud-label,.medkits .hud-label{margin-right:auto}
 .medkits>span:last-child{display:none}
 .story-caption{left:12px;right:12px;bottom:calc(env(safe-area-inset-bottom) + 37%);width:auto;padding:10px 12px}
 .story-caption p{font-size:10px;line-height:1.55;margin:6px 0}
 .caption-speaker{font-size:7px}
 .interact-prompt{top:52%;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px}
 .toast{top:calc(env(safe-area-inset-top) + 70px);left:50%;transform:translateX(-50%);width:max-content;max-width:calc(100% - 24px);font-size:8px;text-align:center}
 .toast.show{transform:translateX(-50%)}
 .pause-card,.end-card{width:min(88%,440px);padding:26px}
}

@media(max-width:700px) and (orientation:portrait){
 .game-shell{width:100vw;height:100dvh;left:0;top:0;transform:none;}
 #game{position:absolute;left:0;top:31%;width:100%;height:auto;aspect-ratio:16/9;object-fit:fill;border-top:1px solid rgba(123,201,194,.3);border-bottom:1px solid rgba(123,201,194,.3);background:#070b0e}
 .scanlines{inset:0;pointer-events:none}
 .hud-top{top:calc(env(safe-area-inset-top) + 12px)}
 .objective{top:calc(100dvh * .16)}
 .hud-bottom{bottom:calc(env(safe-area-inset-bottom) + 20%)}
 .story-caption{bottom:calc(env(safe-area-inset-bottom) + 38%)}
 .interact-prompt{top:52%}
}

@media(max-width:700px) and (orientation:landscape){
 #game{position:absolute;inset:0;width:100%;height:100%;}
 .mobile-controls .move-controls{bottom:calc(env(safe-area-inset-bottom) + 12px)}
 .mobile-controls .mobile-actions{bottom:calc(env(safe-area-inset-bottom) + 12px)}
 .hud-bottom{bottom:calc(env(safe-area-inset-bottom) + 104px);}
 .story-caption{bottom:calc(env(safe-area-inset-bottom) + 112px)}
}
@media(max-width:380px) and (orientation:portrait){
 .mobile-controls .move-controls{left:8px;gap:5px}
 .mobile-controls .mobile-actions{right:8px;grid-template-columns:64px 43px 43px;gap:5px}
 .mobile-controls .move-controls button{width:44px;height:50px}
 .mobile-controls .move-controls .jump-button{width:50px}
 .hud-bottom{left:8px;right:8px;gap:4px}
 .hud-bottom>div{padding:6px 5px}
}
@media(prefers-reduced-motion:reduce){.mobile-controls button,.primary-button,.text-button{transition:none}}

