  function coreStory(n){return n===1?'Esto es el registro de la doctora Imani: el organismo llegó en la sonda Orfeo. No era un parásito. Era una colonia dormida, adaptada al vacío.' : n===2?'Los congelaron para estudiarlos. El calor los despertó. Se anclaron al sistema nervioso y copiaron recuerdos… por eso usaban nuestras voces.':'La colonia no infectó a la tripulación para alimentarse. Construyó una mente colectiva. La señal de auxilio… es un señuelo para que alguien la saque de aquí.'}
  function updateHud(){ui.health.style.width=`${player.hp}%`;ui.healthValue.textContent=Math.ceil(player.hp);ui.ammo.textContent=player.ammo;ui.reserve.textContent=player.reserve;ui.med.textContent=player.med;ui.cores.textContent=cores;}
  function spawnEnemy(x,type){if(enemies.filter(e=>e.hp>0).length>=9)return;const t=type||(['crawler','stalker','crawler'][Math.floor(Math.random()*3)]);enemies.push({x:clamp(x,30,WORLD-50),y:FLOOR-52,w:t==='brute'?54:40,h:t==='crawler'?36:52,hp:t==='brute'?6:t==='stalker'?3:2,max:t==='brute'?6:t==='stalker'?3:2,type:t,vx:0,attack:rand(.3,1.3),flash:0,phase:rand(0,7),dir:1});}
  function shoot(){if(shotCooldown>0)return;if(player.ammo<=0){showToast('CARGADOR VACÍO // [R] RECARGAR',1300);shotCooldown=.35;sound(80,.08);return}player.ammo--;shotCooldown=.24;player.flash=.08;screenShake=2;const px=player.x+player.w/2,py=player.y+22;let tx=input.mouse.x+cam,ty=input.mouse.y; if(input.mobileFire){const target=enemies.filter(e=>e.hp>0).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(target){tx=target.x;ty=target.y-20}else{tx=px+player.facing*300;ty=py-20}}else{tx=(input.mouse.x-sceneOffsetX)/sceneZoom+cam;ty=(input.mouse.y-sceneOffsetY)/sceneZoom;}
    let dx=tx-px,dy=ty-py;const d=Math.hypot(dx,dy)||1;dx/=d;dy/=d;if(Math.abs(dx)>.15)player.facing=Math.sign(dx);bullets.push({x:px+dx*20,y:py+dy*10,vx:dx*790,vy:dy*790,life:.8});sound(210,.065,'sawtooth',.025);updateHud()}
  function damagePlayer(amount){if(player.invuln>0)return;player.hp=Math.max(0,player.hp-amount);player.invuln=.7;screenShake=10;player.vx-=player.facing*130;updateHud();sound(75,.18,'sawtooth',.04);if(player.hp<=0)setEnd(false)}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-150,150),vy:rand(-190,80),life:rand(.2,.6),max:.6,color,size:rand(2,5)})}
  function update(dt){time+=dt;shotCooldown=Math.max(0,shotCooldown-dt);if(toastTimer>0&&(toastTimer-=dt*1000)<=0)ui.toast.classList.remove('show');if(captionTimer>0&&(captionTimer-=dt*1000)<=0)hideCaption();if(player.invuln>0)player.invuln-=dt;if(player.flash>0)player.flash-=dt;screenShake=Math.max(0,screenShake-dt*24);
    const left=input.keys.has('a')||input.keys.has('arrowleft')||input.touch.has('left'),right=input.keys.has('d')||input.keys.has('arrowright')||input.touch.has('right'),up=input.keys.has('w')||input.keys.has('arrowup')||input.touch.has('up'),down=input.keys.has('s')||input.keys.has('arrowdown')||input.touch.has('down');
    const axis=(right?1:0)-(left?1:0);if(axis){player.vx+=axis*1700*dt;player.facing=axis}else player.vx*=Math.pow(.001,dt);player.vx=clamp(player.vx,-280,280);
    if((input.keys.has(' ')||input.keys.has('w')||input.keys.has('arrowup')||input.touch.has('up'))&&player.grounded){player.vy=-520;player.grounded=false;sound(130,.05,'sine',.01)}
    player.vy+=1450*dt;player.x=clamp(player.x+player.vx*dt,0,WORLD-player.w);player.y+=player.vy*dt;if(player.y+player.h>=FLOOR){player.y=FLOOR-player.h;player.vy=0;player.grounded=true}
