/* Opening story crawl and soft screen-to-screen transitions. */
.screen{transition:opacity .9s ease}
.screen.is-fading{opacity:0;pointer-events:none}
.screen.is-visible{opacity:1}
.intro-cinematic{overflow:hidden;background:radial-gradient(ellipse at 50% 42%,rgba(19,31,37,.96),rgba(4,7,11,.99) 72%);opacity:0;}
.intro-cinematic.is-visible{opacity:1}
.intro-vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,#05080d 0%,transparent 18%,transparent 78%,#05080d 100%),radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.62) 100%)}
.intro-viewport{position:absolute;inset:0;overflow:hidden;perspective:700px}
.opening-crawl{position:absolute;left:50%;top:0;width:min(590px,76%);padding:0 12px;text-align:center;color:#d6d9d2;font-family:var(--display);font-size:clamp(18px,2.1vw,27px);font-weight:500;line-height:1.55;letter-spacing:.025em;transform:translateX(-50%);animation:opening-crawl 42s linear forwards;}
.opening-crawl p{margin:0 0 1.45em}
.opening-crawl .crawl-label{margin-bottom:26px;color:var(--cyan);font:11px var(--mono);letter-spacing:.2em}
.opening-crawl h2{margin:0 0 1.1em;color:#f0eee3;font-size:clamp(52px,8vw,88px);line-height:.83;letter-spacing:.015em}
.opening-crawl h2 em,.opening-crawl .crawl-final em{color:var(--red);font-style:normal}
.opening-crawl .crawl-final{margin-top:2.1em;color:#f0eee3;font-size:1.12em}
@keyframes opening-crawl{from{transform:translate(-50%,72vh)}to{transform:translate(-50%,-115%)}}
.skip-cinematic{position:absolute;z-index:3;top:5%;right:5%;min-height:42px;padding:0 15px;border:1px solid rgba(172,190,183,.4);border-radius:2px;background:rgba(7,12,16,.72);color:#c6ceca;font:10px var(--mono);letter-spacing:.1em;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
.skip-cinematic:hover,.skip-cinematic:focus-visible{background:rgba(27,42,45,.95);border-color:var(--cyan);color:#fff;outline:none}
.skip-cinematic span{margin-left:10px;color:var(--cyan)}
.cinematic-progress{position:absolute;z-index:3;left:0;right:0;bottom:0;height:2px;background:rgba(255,255,255,.1)}
