139:  .move-controls button,.mobile-actions button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;border:1px solid rgba(173,195,186,.48);border-radius:13px;background:linear-gradient(145deg,rgba(27,39,42,.96),rgba(8,14,17,.97));color:#edf1e9;box-shadow:0 6px 18px #0009,inset 0 1px #ffffff12}
140:  .mobile-controls .move-controls button{width:49px;height:53px;font:26px/1 var(--display)}
141:  .mobile-controls .move-controls .jump-button{width:56px;color:var(--cyan)}
