143:  .mobile-controls .mobile-actions{position:absolute;left:auto;right:max(12px,env(safe-area-inset-right));bottom:calc(env(safe-area-inset-bottom) + 22px);top:auto;display:grid;grid-template-columns:70px 47px 47px;grid-template-rows:43px 43px;gap:7px;pointer-events:auto}
144:  .mobile-controls .mobile-actions button{width:auto;height:auto;min-width:0;font:inherit}
145:  .mobile-controls .mobile-actions .fire-button{grid-column:1;grid-row:1/3;border-radius:22px;border-color:rgba(228,105,91,.76);background:radial-gradient(circle at 35% 25%,rgba(137,58,50,.98),rgba(49,21,22,.99));color:#fff2e8}
146:  .mobile-actions .fire-button span{font-size:24px}
147:  .mobile-controls .mobile-actions #mobileUse{grid-column:2;grid-row:1;color:var(--cyan)}
148:  .mobile-controls .mobile-actions #mobileReload{grid-column:3;grid-row:1;color:#e3d7ab}
149:  .mobile-controls .mobile-actions #mobileMed{grid-column:2/4;grid-row:2}
150:  .mobile-controls .mobile-pause{position:absolute;top:calc(env(safe-area-inset-top) + 12px);right:max(12px,env(safe-area-inset-right));left:auto;bottom:auto;width:44px;height:42px;pointer-events:auto;font:18px/1 var(--mono)}
151:  .hud{position:absolute;inset:0;z-index:7;pointer-events:none}
152:  .hud-top{position:absolute;left:12px;right:68px;top:calc(env(safe-area-inset-top) + 12px);display:grid;grid-template-columns:1fr auto;align-items:start;gap:8px}
153:  .hud-brand{min-width:0;padding:7px 9px;border-radius:4px;gap:8px}
154:  .hud-brand small{font-size:6px;letter-spacing:.06em}
155:  .hud-brand b{font-size:10px}
156:  .objective{position:absolute!important;left:0;right:0;top:calc(100dvh * .125);width:auto!important;padding:8px 10px!important}
157:  .objective small,.sector small{font-size:7px}
158:  .objective b,.sector b{font-size:9px;line-height:1.25}
159:  .sector{grid-column:2;grid-row:1;margin:0;padding:7px 9px!important;text-align:right;border-radius:4px}
160:  .hud-bottom{position:absolute;left:12px;right:12px;top:auto;bottom:calc(env(safe-area-inset-bottom) + 19%);display:grid;grid-template-columns:1.25fr 1fr 1fr;gap:6px;align-items:stretch}
161:  .hud-bottom>div{min-width:0;padding:7px 8px;border-radius:4px}
162:  .vitals{grid-template-columns:auto minmax(28px,1fr) 22px;gap:5px}
163:  .hud-label{font-size:6px;letter-spacing:.08em}
164:  .health-track{height:4px}
165:  .health-value,.vitals>b,.ammo>b,.collectibles>b,.medkits>b{font-size:11px}
166:  .ammo{padding-left:8px!important;gap:4px}
167:  .ammo-icon{font-size:10px}
168:  .collectibles,.medkits{margin:0!important;display:flex;align-items:center;gap:4px}
169:  .collectibles .hud-label,.medkits .hud-label{margin-right:auto}
170:  .medkits>span:last-child{display:none}
171:  .story-caption{left:12px;right:12px;bottom:calc(env(safe-area-inset-bottom) + 37%);width:auto;padding:10px 12px}
172:  .story-caption p{font-size:10px;line-height:1.55;margin:6px 0}
173:  .caption-speaker{font-size:7px}
174:  .interact-prompt{top:52%;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px}
175:  .toast{top:calc(env(safe-area-inset-top) + 70px);left:50%;transform:translateX(-50%);width:max-content;max-width:calc(100% - 24px);font-size:8px;text-align:center}
