203:  .toast{top:106px;left:50%;transform:translateX(-50%);width:max-content;max-width:calc(100% - 24px);font-size:8px;text-align:center}
204:  .toast.show{transform:translateX(-50%)}
205: }
206: @media(max-width:380px) and (orientation:portrait){
